[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WellStream Platform — Integrated Energy Data Management</title>
  <meta name="title" content="WellStream Platform — Integrated Energy Data Management">
  <meta name="description" content="The integrated energy data platform built for operators who demand speed, security, and visibility across the well data lifecycle.">
  <link rel="canonical" href="https://wellstream.com/">
  <meta property="og:type" content="website">
  <meta property="og:url" content="https://wellstream.com/">
  <meta property="og:title" content="WellStream Platform — Integrated Energy Data Management">
  <meta property="og:description" content="The integrated energy data platform built for operators who demand speed, security, and visibility across the well data lifecycle.">
  <meta property="twitter:card" content="summary_large_image">
  <link rel="icon" type="image/svg+xml" href="favicon.svg">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --navy: #15295A;
      --dark-gray: #3C424B;
      --teal: #00B4D8;
      --blue: #0077B6;
      --bg-dark: #0D1B2A;
      --bg-card: #1B2838;
      --text-primary: #ffffff;
      --text-secondary: #a0aec0;
      --text-muted: #718096;
    }
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: 'Inter', sans-serif; background: var(--bg-dark); color: var(--text-primary); line-height: 1.6; }
    a { text-decoration: none; color: inherit; }
    img { max-width: 100%; }
    .container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }

    /* Header */
    .header { position: fixed; top: 0; left: 0; right: 0; z-index: 1000; background: rgba(13, 27, 42, 0.95); backdrop-filter: blur(12px); border-bottom: 1px solid rgba(255,255,255,0.06); }
    .header-inner { display: flex; align-items: center; justify-content: space-between; padding: 0 24px; height: 72px; max-width: 1400px; margin: 0 auto; }
    .logo { font-size: 1.5rem; font-weight: 800; color: var(--teal); letter-spacing: -0.5px; }
    .logo span { color: var(--text-primary); }
    .nav { display: flex; align-items: center; gap: 32px; }
    .nav-dropdown { position: relative; }
    .nav-dropdown-btn { display: flex; align-items: center; gap: 6px; font-size: 0.9rem; font-weight: 500; color: var(--text-secondary); cursor: pointer; transition: color 0.2s; }
    .nav-dropdown-btn:hover { color: var(--text-primary); }
    .nav-dropdown-btn::after { content: '▾'; font-size: 0.7rem; }
    .nav-dropdown-menu { position: absolute; top: 100%; left: -12px; margin-top: 12px; background: var(--bg-card); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; padding: 8px; min-width: 200px; opacity: 0; visibility: hidden; transform: translateY(-8px); transition: all 0.2s; }
    .nav-dropdown:hover .nav-dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
    .nav-dropdown-menu a { display: block; padding: 10px 16px; font-size: 0.875rem; color: var(--text-secondary); border-radius: 8px; transition: all 0.15s; }
    .nav-dropdown-menu a:hover { background: rgba(0,180,216,0.1); color: var(--teal); }
    .nav-links { display: flex; align-items: center; gap: 28px; }
    .nav-links a { font-size: 0.9rem; font-weight: 500; color: var(--text-secondary); transition: color 0.2s; }
    .nav-links a:hover { color: var(--text-primary); }
    .btn-demo { background: linear-gradient(135deg, var(--teal), var(--blue)); color: #fff; padding: 10px 24px; border-radius: 8px; font-weight: 600; font-size: 0.875rem; transition: all 0.2s; box-shadow: 0 2px 12px rgba(0,180,216,0.3); }
    .btn-demo:hover { transform: translateY(-1px); box-shadow: 0 4px 20px rgba(0,180,216,0.4); }
    .mobile-toggle { display: none; background: none; border: none; cursor: pointer; padding: 8px; }
    .mobile-toggle span { display: block; width: 24px; height: 2px; background: var(--text-primary); margin: 5px 0; border-radius: 2px; }

    /* Hero */
    .hero { min-height: 100vh; display: flex; align-items: center; padding: 120px 24px 80px; position: relative; overflow: hidden; }
    .hero::before { content: ''; position: absolute; inset: 0; background: radial-gradient(ellipse 80% 60% at 50% 40%, rgba(0,180,216,0.08) 0%, transparent 70%); pointer-events: none; }
    .hero-grid { position: absolute; inset: 0; background-image: linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px); background-size: 60px 60px; pointer-events: none; }
    .hero-content { max-width: 800px; margin: 0 auto; text-align: center; position: relative; z-index: 1; }
    .hero-eyebrow { display: inline-flex; align-items: center; gap: 8px; background: rgba(0,180,216,0.1); border: 1px solid rgba(0,180,216,0.2); padding: 8px 16px; border-radius: 50px; font-size: 0.8rem; font-weight: 600; color: var(--teal); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 24px; }
    .hero h1 { font-size: clamp(2.5rem, 6vw, 4rem); font-weight: 800; line-height: 1.1; margin-bottom: 24px; background: linear-gradient(135deg, #fff 0%, #a0aec0 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
    .hero p { font-size: 1.125rem; color: var(--text-secondary); max-width: 600px; margin: 0 auto 40px; line-height: 1.7; }
    .hero-btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
    .btn-primary { background: linear-gradient(135deg, var(--teal), var(--blue)); color: #fff; padding: 14px 32px; border-radius: 10px; font-weight: 600; font-size: 1rem; transition: all 0.2s; box-shadow: 0 4px 20px rgba(0,180,216,0.35); }
    .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 6px 30px rgba(0,180,216,0.5); }
    .btn-secondary { background: transparent; border: 1px solid rgba(255,255,255,0.2); color: var(--text-primary); padding: 14px 32px; border-radius: 10px; font-weight: 600; font-size: 1rem; transition: all 0.2s; }
    .btn-secondary:hover { background: rgba(255,255,255,0.05); border-color: rgba(255,255,255,0.3); }

    /* Featured Banner */
    .featured-banner { background: linear-gradient(135deg, var(--navy) 0%, #1a2d4a 100%); border: 1px solid rgba(0,180,216,0.15); border-radius: 16px; padding: 48px; margin: 0 24px 80px; display: flex; align-items: center; justify-content: space-between; gap: 32px; }
    .featured-badge { display: inline-flex; align-items: center; gap: 8px; background: rgba(108,194,74,0.15); border: 1px solid rgba(108,194,74,0.3); padding: 6px 14px; border-radius: 50px; font-size: 0.75rem; font-weight: 700; color: var(--accent); color: #6CC24A; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 16px; }
    .featured-info h3 { font-size: 1.75rem; font-weight: 700; margin-bottom: 8px; }
    .featured-info p { color: var(--text-secondary); font-size: 1rem; max-width: 500px; }
    .btn-learn { background: #6CC24A; color: #0D1B2A; padding: 12px 24px; border-radius: 8px; font-weight: 700; font-size: 0.875rem; transition: all 0.2s; }
    .btn-learn:hover { background: #7dcf5a; transform: translateY(-1px); }

    /* Industry Tabs */
    .use-cases { padding: 0 24px 80px; }
    .section-label { font-size: 0.75rem; font-weight: 700; color: var(--teal); text-transform: uppercase; letter-spacing: 2px; margin-bottom: 12px; }
    .section-title { font-size: clamp(1.75rem, 4vw, 2.5rem); font-weight: 700; margin-bottom: 16px; }
    .section-desc { color: var(--text-secondary); max-width: 700px; line-height: 1.7; margin-bottom: 48px; }
    .industry-tabs { display: flex; gap: 4px; background: var(--bg-card); border-radius: 12px; padding: 6px; margin-bottom: 40px; flex-wrap: wrap; }
    .industry-tab { flex: 1; min-width: 100px; padding: 12px 20px; border-radius: 8px; font-size: 0.875rem; font-weight: 600; color: var(--text-secondary); cursor: pointer; transition: all 0.2s; text-align: center; border: none; background: none; }
    .industry-tab:hover { color: var(--text-primary); }
    .industry-tab.active { background: var(--teal); color: #fff; }
    .tab-content { display: none; }
    .tab-content.active { display: block; }

    /* Use Case Grid */
    .use-case-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); gap: 20px; }
    .use-case-card { background: var(--bg-card); border: 1px solid rgba(255,255,255,0.06); border-radius: 16px; padding: 32px; transition: all 0.25s; cursor: pointer; }
    .use-case-card:hover { border-color: rgba(0,180,216,0.3); transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.3); }
    .use-case-icon { width: 48px; height: 48px; background: linear-gradient(135deg, rgba(0,180,216,0.15), rgba(0,119,182,0.1)); border-radius: 12px; display: flex; align-items: center; justify-content: center; margin-bottom: 20px; }
    .use-case-icon svg { width: 24px; height: 24px; stroke: var(--teal); fill: none; stroke-width: 2; }
    .use-case-card h4 { font-size: 1.125rem; font-weight: 600; margin-bottom: 10px; }
    .use-case-card p { font-size: 0.9rem; color: var(--text-secondary); line-height: 1.6; }

    /* Platform Ecosystem Diagram */
    .ecosystem { padding: 80px 24px; background: linear-gradient(180deg, transparent 0%, rgba(0,180,216,0.03) 100%); }
    .ecosystem-diagram { max-width: 1000px; margin: 0 auto; }
    .ecosystem-svg { width: 100%; height: auto; }
    .ecosystem-legend { display: flex; justify-content: center; gap: 48px; margin-top: 40px; flex-wrap: wrap; }
    .legend-item { display: flex; align-items: center; gap: 12px; }
    .legend-dot { width: 16px; height: 16px; border-radius: 50%; }
    .legend-dot.purple { background: #9B59B6; }
    .legend-dot.blue { background: var(--teal); }
    .legend-dot.green { background: #6CC24A; }
    .legend-text { font-size: 0.9rem; font-weight: 500; color: var(--text-secondary); }

    /* Company Culture */
    .culture { padding: 80px 24px; }
    .culture-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .culture-visual { background: linear-gradient(135deg, var(--navy) 0%, #1a2d4a 100%); border-radius: 20px; padding: 48px; text-align: center; border: 1px solid rgba(0,180,216,0.1); }
    .culture-stat { margin-bottom: 32px; }
    .culture-stat:last-child { margin-bottom: 0; }
    .culture-stat-value { font-size: 3rem; font-weight: 800; color: var(--teal); }
    .culture-stat-label { font-size: 0.9rem; color: var(--text-secondary); margin-top: 4px; }
    .culture h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); font-weight: 700; margin-bottom: 24px; }
    .culture p { color: var(--text-secondary); line-height: 1.8; margin-bottom: 32px; }
    .btn-outline { display: inline-flex; align-items: center; gap: 8px; background: transparent; border: 1px solid rgba(255,255,255,0.2); color: var(--text-primary); padding: 12px 24px; border-radius: 8px; font-weight: 600; transition: all 0.2s; }
    .btn-outline:hover { background: rgba(255,255,255,0.05); border-color: var(--teal); color: var(--teal); }

    /* Renewables CTA */
    .renewables { padding: 80px 24px; background: linear-gradient(135deg, rgba(108,194,74,0.08) 0%, rgba(0,180,216,0.05) 100%); border-top: 1px solid rgba(108,194,74,0.15); border-bottom: 1px solid rgba(108,194,74,0.15); }
    .renewables-inner { max-width: 800px; margin: 0 auto; text-align: center; }
    .renewables h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); font-weight: 700; margin-bottom: 16px; }
    .renewables p { color: var(--text-secondary); line-height: 1.7; margin-bottom: 32px; max-width: 600px; margin-left: auto; margin-right: auto; }
    .products { display: flex; justify-content: center; gap: 16px; margin-bottom: 32px; flex-wrap: wrap; }
    .product-tag { background: rgba(108,194,74,0.15); border: 1px solid rgba(108,194,74,0.25); padding: 8px 16px; border-radius: 8px; font-size: 0.875rem; font-weight: 600; color: #6CC24A; }

    /* Footer */
    .footer { background: #0a1520; border-top: 1px solid rgba(255,255,255,0.06); padding: 64px 24px 32px; }
    .footer-grid { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 48px; max-width: 1280px; margin: 0 auto; }
    .footer-brand p { color: var(--text-muted); font-size: 0.875rem; margin-top: 16px; line-height: 1.7; }
    .footer-col h5 { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: var(--text-muted); margin-bottom: 20px; }
    .footer-col a { display: block; font-size: 0.875rem; color: var(--text-secondary); margin-bottom: 12px; transition: color 0.2s; }
    .footer-col a:hover { color: var(--teal); }
    .footer-bottom { max-width: 1280px; margin: 48px auto 0; padding-top: 24px; border-top: 1px solid rgba(255,255,255,0.06); display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
    .footer-bottom p { font-size: 0.8rem; color: var(--text-muted); }
    .footer-links { display: flex; gap: 24px; }
    .footer-links a { font-size: 0.8rem; color: var(--text-muted); transition: color 0.2s; }
    .footer-links a:hover { color: var(--teal); }
    .portal-links { display: flex; gap: 12px; margin-top: 24px; }
    .portal-btn { background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); padding: 8px 16px; border-radius: 6px; font-size: 0.8rem; font-weight: 500; color: var(--text-secondary); transition: all 0.2s; }
    .portal-btn:hover { border-color: var(--teal); color: var(--teal); }

    /* Cookie Banner */
    .cookie-banner { position: fixed; bottom: 24px; left: 24px; right: 24px; max-width: 480px; background: var(--bg-card); border: 1px solid rgba(255,255,255,0.1); border-radius: 16px; padding: 24px; z-index: 999; box-shadow: 0 20px 60px rgba(0,0,0,0.5); display: none; }
    .cookie-banner.show { display: block; }
    .cookie-banner h4 { font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
    .cookie-banner p { font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 20px; line-height: 1.6; }
    .cookie-btns { display: flex; gap: 12px; }
    .cookie-accept { background: var(--teal); color: #fff; border: none; padding: 10px 20px; border-radius: 8px; font-weight: 600; font-size: 0.875rem; cursor: pointer; transition: all 0.2s; }
    .cookie-decline { background: transparent; border: 1px solid rgba(255,255,255,0.2); color: var(--text-secondary); padding: 10px 20px; border-radius: 8px; font-weight: 600; font-size: 0.875rem; cursor: pointer; transition: all 0.2s; }
    .cookie-accept:hover { background: #00a3c4; }
    .cookie-decline:hover { border-color: rgba(255,255,255,0.4); color: var(--text-primary); }

    /* Responsive */
    @media (max-width: 1024px) {
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .culture-grid { grid-template-columns: 1fr; }
      .featured-banner { flex-direction: column; text-align: center; }
    }
    @media (max-width: 768px) {
      .nav-links { display: none; }
      .mobile-toggle { display: block; }
      .header-inner { height: 64px; }
      .hero { padding-top: 100px; }
      .footer-grid { grid-template-columns: 1fr; }
      .use-case-grid { grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>
  <!-- Header -->
  <header class="header">
    <div class="header-inner">
      <a href="index.html" class="logo">Well<span>Stream</span></a>
      <nav class="nav">
