  <!-- Use Cases with Industry Tabs -->
  <section class="use-cases container">
    <div class="section-label">USE CASES</div>
    <h2 class="section-title">See the WellStream Platform in Action</h2>
    <p class="section-desc">From drilling to production, land to water, watch how WellStream transforms every phase of your operations. Streamline workflows, unlock real-time insights, and make every decision count with seamless, end-to-end data integration.</p>

    <div class="industry-tabs">
      <button class="industry-tab active" data-tab="ep">E&P</button>
      <button class="industry-tab" data-tab="midstream">Midstream</button>
      <button class="industry-tab" data-tab="downstream">Downstream</button>
      <button class="industry-tab" data-tab="utilities">Utilities</button>
